-- Chapitre 4 : écritures et transactions
-- Bibliothèque des Lilas : solution complète.

-- 1. Insertion multi-lignes, colonnes listées explicitement.
INSERT INTO lecteurs (identifiant, nom, prenom, courriel, date_inscription)
VALUES (21, 'Fabre', 'Nina', 'nina.fabre@example.fr', '2026-03-02'),
       (22, 'Ouedraogo', 'Idriss', 'idriss.o@example.fr', '2026-03-02');

-- 2. Import à partir d'une table d'attente.
INSERT INTO ouvrages (identifiant, titre, auteur, isbn)
SELECT identifiant, titre, auteur, isbn
FROM ouvrages_en_attente
WHERE valide = true
  AND NOT EXISTS (
    SELECT 1 FROM ouvrages o WHERE o.isbn = ouvrages_en_attente.isbn
  );

-- 3. Lecture de contrôle puis mise à jour conditionnée.
SELECT COUNT(*) FROM exemplaires WHERE etat = 'perdu';

UPDATE exemplaires
SET etat = 'bon'
WHERE etat = 'perdu'
  AND date_reforme IS NULL;

SELECT COUNT(*) FROM exemplaires WHERE etat = 'perdu';

-- 4. Suppression sécurisée des réservations périmées.
SELECT COUNT(*) FROM reservations WHERE date_demande < '2025-06-01';

DELETE FROM reservations
WHERE date_demande < '2025-06-01'
  AND ouvrage_id IS NULL;

SELECT COUNT(*) FROM reservations WHERE date_demande < '2025-06-01';

-- 5. Enregistrement d'un emprunt dans une transaction.
BEGIN;

SELECT COUNT(*) FROM exemplaires WHERE identifiant = 101 AND etat = 'neuf';

INSERT INTO emprunts (identifiant, lecteur_id, date_sortie)
VALUES (9100, 21, '2026-03-04');

UPDATE exemplaires
SET etat = 'emprunté', emprunt_id = 9100
WHERE identifiant = 101 AND etat = 'neuf';

SELECT etat FROM exemplaires WHERE identifiant = 101;

COMMIT;

-- Cas d'échec : exemplaire indisponible, on annule tout.
BEGIN;

SELECT COUNT(*) FROM exemplaires WHERE identifiant = 102 AND etat = 'neuf';

UPDATE exemplaires
SET etat = 'emprunté', emprunt_id = 9101
WHERE identifiant = 102 AND etat = 'neuf';

ROLLBACK;

-- 6. Virement de provision entre deux comptes.
BEGIN;

SELECT solde FROM comptes WHERE numero = 'FR111';

UPDATE comptes
SET solde = solde - 150
WHERE numero = 'FR111'
  AND solde >= 150;

UPDATE comptes
SET solde = solde + 150
WHERE numero = 'FR222';

INSERT INTO ecritures (compte_debit, compte_credit, montant, date_operation)
VALUES ('FR111', 'FR222', 150, '2026-03-04');

SELECT solde FROM comptes WHERE numero = 'FR111';

COMMIT;
